const todos: Record<string, () => Algo> = { "a-estrela": aestrela, "fluxo-maximo": fluxoMax, "shunting-yard": shunting, "tarjan-scc": tarjan, "kmp": kmp, "union-find": unionFind, "mochila-01": mochila, "n-rainhas": rainhas, "distancia-edicao": edicao, "dijkstra": dijkstra, "ordenacao-topologica": kahn, "cache-lru": lru, "busca-binaria": buscaBinaria, "janela-sem-repeticao": janelaSemRepeticao, "merge-intervalos": mergeIntervalos };
const want = process.argv.slice(2);
mkdirSync("examples/exemplos-algoritmos", { recursive: true });
for (const [nome, make] of Object.entries(todos)) {
  if (want.length && !want.includes(nome)) continue;
  const a = make();
  writeFileSync(`examples/exemplos-algoritmos/${nome}.archflow.json`, JSON.stringify(a.doc, null, 2));
  writeFileSync(`src/shared/fixtures/oracles/${nome}.json`, JSON.stringify({ enunciado: a.enunciado, cases: a.oraculo }, null, 2));
  console.log("ok", nome);
}
